448	// registerConnection holds onto conn so it can be closed in the event
449	// of a server shutdown. This is useful because hijacked connections or
450	// connections dialed to backends don't close when server is shut down.
451	// The caller should call the returned delete() function when the
452	// connection is done to remove it from memory.
453	func (h *Handler) registerConnection(oc openConnection) (del func()) {
454		h.connectionsMu.Lock()
455		h.connections[oc.conn] = oc
456		h.connectionsMu.Unlock()
457		return func() {
458			h.connectionsMu.Lock()
459			delete(h.connections, oc.conn)
460			// if there is no connection left before the connections close timer fires
461			if len(h.connections) == 0 && h.connectionsCloseTimer != nil {
462				// we release the timer that holds the reference to Handler
463				if (*h.connectionsCloseTimer).Stop() {
464					h.logger.Debug("stopped streaming connections close timer - all connections are already closed")
465				}
466				h.connectionsCloseTimer = nil
467			}
468			h.connectionsMu.Unlock()
469		}
470	}
