472	// closeConnections immediately closes all hijacked connections (both to client and backend).
473	func (h *Handler) closeConnections() error {
474		var err error
475		h.connectionsMu.Lock()
476		defer h.connectionsMu.Unlock()
477	
478		for _, oc := range h.connections {
479			oc.stream.setReason(streamResultShutdown)
480			// this is potentially blocking while we have the lock on the connections
481			// map, but that should be OK since the server has in theory shut down
482			// and we are no longer using the connections map
483			if closeErr := oc.close(); closeErr != nil && err == nil {
484				err = closeErr
485			}
486		}
487		return err
488	}
