490	// cleanupConnections closes hijacked connections.
491	// Depending on the value of StreamCloseDelay it does that either immediately
492	// or sets up a timer that will do that later.
493	func (h *Handler) cleanupConnections() error {
494		if h.StreamCloseDelay == 0 {
495			return h.closeConnections()
496		}
497	
498		h.connectionsMu.Lock()
499		defer h.connectionsMu.Unlock()
500		// the handler is shut down, no new connection can appear,
501		// so we can skip setting up the timer when there are no connections
502		if len(h.connections) > 0 {
503			delay := time.Duration(h.StreamCloseDelay)
504			h.connectionsCloseTimer = time.AfterFunc(delay, func() {
505				if c := h.logger.Check(zapcore.DebugLevel, "closing streaming connections after delay"); c != nil {
506					c.Write(zap.Duration("delay", delay))
507				}
508				err := h.closeConnections()
509				if err != nil {
510					if c := h.logger.Check(zapcore.ErrorLevel, "failed to closed connections after delay"); c != nil {
511						c.Write(
512							zap.Error(err),
513							zap.Duration("delay", delay),
514						)
515					}
516				}
517			})
518		}
519		return nil
520	}
