522	// writeCloseControl sends a best-effort Close control message to the given
523	// WebSocket connection. Thanks to @pascaldekloe who provided inspiration
524	// from his simple implementation of this I was able to learn from at:
525	// github.com/pascaldekloe/websocket. Further work for handling masking
526	// taken from github.com/gorilla/websocket.
527	func writeCloseControl(conn io.Writer, isClient bool) error {
528		// Sources:
529		// https://github.com/pascaldekloe/websocket/blob/32050af67a5d/websocket.go#L119
530		// https://github.com/gorilla/websocket/blob/v1.5.0/conn.go#L413
531	
532		// For now, we're not using a reason. We might later, though.
533		// The code handling the reason is left in
534		var reason string // max 123 bytes (control frame payload limit is 125; status code takes 2)
535	
536		const closeMessage = 8
537		const finalBit = 1 << 7 // Frame header byte 0 bits from Section 5.2 of RFC 6455
538		const maskBit = 1 << 7  // Frame header byte 1 bits from Section 5.2 of RFC 6455
539		const goingAwayUpper uint8 = 1001 >> 8
540		const goingAwayLower uint8 = 1001 & 0xff
541	
542		b0 := byte(closeMessage) | finalBit
543		b1 := byte(len(reason) + 2)
544		if isClient {
545			b1 |= maskBit
546		}
547	
548		buf := make([]byte, 0, 127)
549		buf = append(buf, b0, b1)
550		msgLength := 4 + len(reason)
551	
552		// Both branches below append the "going away" code and reason
553		appendMessage := func(buf []byte) []byte {
554			buf = append(buf, goingAwayUpper, goingAwayLower)
555			buf = append(buf, []byte(reason)...)
556			return buf
557		}
558	
559		// When we're the client, we need to mask the message as per
560		// https://www.rfc-editor.org/rfc/rfc6455#section-5.3
561		if isClient {
562			key := newMaskKey()
563			buf = append(buf, key[:]...)
564			msgLength += len(key)
565			buf = appendMessage(buf)
566			maskBytes(key, 0, buf[2+len(key):])
567		} else {
568			buf = appendMessage(buf)
569		}
570	
571		// simply best-effort, but return error for logging purposes
572		// TODO: we might need to ensure we are the exclusive writer by this point (io.Copy is stopped)?
573		_, err := conn.Write(buf[:msgLength])
574		return err
575	}
