577	// Copied from https://github.com/gorilla/websocket/blob/v1.5.0/mask.go
578	func maskBytes(key [4]byte, pos int, b []byte) int {
579		// Mask one byte at a time for small buffers.
580		if len(b) < 2*wordSize {
581			for i := range b {
582				b[i] ^= key[pos&3]
583				pos++
584			}
585			return pos & 3
586		}
587	
588		// Mask one byte at a time to word boundary.
589		if n := int(uintptr(unsafe.Pointer(&b[0]))) % wordSize; n != 0 {
590			n = wordSize - n
591			for i := range b[:n] {
592				b[i] ^= key[pos&3]
593				pos++
594			}
595			b = b[n:]
596		}
597	
598		// Create aligned word size key.
599		var k [wordSize]byte
600		for i := range k {
601			k[i] = key[(pos+i)&3] // nolint:gosec // false positive, impossible to be out of bounds; see: https://github.com/securego/gosec/issues/1525
602		}
603		kw := *(*uintptr)(unsafe.Pointer(&k))
604	
605		// Mask one word at a time.
606		n := (len(b) / wordSize) * wordSize
607		for i := 0; i < n; i += wordSize {
608			*(*uintptr)(unsafe.Add(unsafe.Pointer(&b[0]), i)) ^= kw
609		}
610	
611		// Mask one byte at a time for remaining bytes.
612		b = b[n:]
613		for i := range b {
614			b[i] ^= key[pos&3]
615			pos++
616		}
617	
618		return pos & 3
619	}
