621	// Copied from https://github.com/gorilla/websocket/blob/v1.5.0/conn.go#L184
622	func newMaskKey() [4]byte {
623		n := weakrand.Uint32()
624		return [4]byte{byte(n), byte(n >> 8), byte(n >> 16), byte(n >> 24)}
625	}
