643	// close gracefully closes the connection, if it can be, then closes it.
644	// It returns the first error that occurred.
645	func (oc openConnection) close() error {
646		var err error
647		if oc.gracefulClose != nil {
648			err = oc.gracefulClose()
649		}
650		if closeErr := oc.conn.Close(); closeErr != nil && err == nil {
651			err = closeErr
652		}
653		return err
654	}
