656	// Results an upgraded stream is accounted with. They are the values
657	// of the "result" label of the closed streams metric.
658	const (
659		streamResultCompleted = "completed"        // both directions ended cleanly
660		streamResultError     = "error"            // a copy failed or a connection broke
661		streamResultTimeout   = "timeout"          // stream_timeout elapsed
662		streamResultCanceled  = "canceled"         // the client request was canceled
663		streamResultShutdown  = "shutdown"         // closed because the config was unloaded
664		streamResultRemoved   = "upstream_removed" // closed because the upstream left the config
