676	// streamState accounts for one upgraded stream. A stream can end in
677	// several racing ways (clean EOF, copy error, timeout, cancellation,
678	// reload), so everything that must happen exactly once at the end of
679	// a stream (metrics, close log) is done by finish, which runs it once.
680	type streamState struct {
681		upstream string
682		start    time.Time
683		onFinish func(streamSummary)
684	
685		toBackend   atomic.Int64
686		fromBackend atomic.Int64
687	
688		mu     sync.Mutex
689		reason string // first reason given for the end of the stream
690	
691		once    sync.Once
692		summary streamSummary
693	}
694	
695	// newStreamState starts accounting for a stream to upstream: it counts as
696	// active until finish is called. onFinish is called once, when it ends.
697	func newStreamState(upstream string, onFinish func(streamSummary)) *streamState {
698		streamMetrics.active.WithLabelValues(upstream).Inc()
699		return &streamState{upstream: upstream, start: time.Now(), onFinish: onFinish}
700	}
701	
702	// setReason records why the stream is ending, if no reason was
703	// recorded yet: the first close path to run determines the result.
704	func (s *streamState) setReason(reason string) {
705		s.mu.Lock()
706		defer s.mu.Unlock()
707		if s.reason == "" {
708			s.reason = reason
709		}
710	}
711	
712	// finish ends the stream with result, unless a reason was recorded before,
713	// then updates the metrics and calls onFinish. Only the first call does
714	// anything, whichever close path it comes from; later calls just return
715	// the summary of the first.
716	func (s *streamState) finish(result string) streamSummary {
717		s.once.Do(func() {
718			s.setReason(result)
719			s.mu.Lock()
720			s.summary = streamSummary{
721				upstream:    s.upstream,
722				result:      s.reason,
723				duration:    time.Since(s.start),
724				toBackend:   s.toBackend.Load(),
725				fromBackend: s.fromBackend.Load(),
726			}
727			s.mu.Unlock()
728	
729			streamMetrics.active.WithLabelValues(s.upstream).Dec()
730			streamMetrics.closed.WithLabelValues(s.upstream, s.summary.result).Inc()
731			streamMetrics.duration.WithLabelValues(s.upstream).Observe(s.summary.duration.Seconds())
732			streamMetrics.bytes.WithLabelValues(s.upstream, streamDirectionToBackend).Add(float64(s.summary.toBackend))
733			streamMetrics.bytes.WithLabelValues(s.upstream, streamDirectionFromBackend).Add(float64(s.summary.fromBackend))
734			s.onFinish(s.summary)
735		})
736		return s.summary
737	}
