780	// closeUpstream closes the registered streams to upstream, and returns
781	// how many there were. Errors closing are not reported: the connections
782	// of a stream that is going away are often already gone.
783	func (r *detachedRegistry) closeUpstream(upstream string) int {
784		var doomed []*detachedStream
785		r.mu.Lock()
786		for ds := range r.streams {
787			if ds.upstream == upstream {
788				doomed = append(doomed, ds)
789				delete(r.streams, ds)
790			}
791		}
792		r.mu.Unlock()
793	
794		// closing may block, so it is not done holding the lock
795		for _, ds := range doomed {
796			for _, oc := range ds.conns {
797				oc.stream.setReason(streamResultRemoved)
798				_ = oc.close()
799			}
800		}
801		return len(doomed)
802	}
