766	// add registers a stream to upstream made of conns. The returned
767	// function removes it again, when the stream is over.
768	func (r *detachedRegistry) add(upstream string, conns ...openConnection) (remove func()) {
769		ds := &detachedStream{upstream: upstream, conns: conns}
770		r.mu.Lock()
771		r.streams[ds] = struct{}{}
772		r.mu.Unlock()
773		return func() {
774			r.mu.Lock()
775			delete(r.streams, ds)
776			r.mu.Unlock()
777		}
778	}
